def fill_output_options(
    target: OutputOptionsStruct,
    *,
    flags: SupportsIndex,
    queue: SupportsIndex,
    max_clients: SupportsIndex,
    datagram_bytes: SupportsIndex,
    reserved0: SupportsIndex,
) -> OutputOptionsStruct:
    """Check every value, then write them all into target (a keel_camera_output_options) and return it.

    Raises TypeError for a value that is not an integer and OverflowError for an integer outside its C type. Nothing is
    written then.
    """
    checked_flags = check_u32("keel_camera_output_options", "flags", flags)
    checked_queue = check_u32("keel_camera_output_options", "queue", queue)
    checked_max_clients = check_u32("keel_camera_output_options", "max_clients", max_clients)
    checked_datagram_bytes = check_u32("keel_camera_output_options", "datagram_bytes", datagram_bytes)
    checked_reserved0 = check_u32("keel_camera_output_options", "reserved0", reserved0)
    target.struct_size = ctypes.sizeof(target)
    target.flags = checked_flags
    target.queue = checked_queue
    target.max_clients = checked_max_clients
    target.datagram_bytes = checked_datagram_bytes
    target.reserved0 = checked_reserved0
    return target


